.tag-filter button{transition:background-color 180ms ease,color 180ms ease,border-color 180ms ease,transform 180ms var(--ease)}.tag-filter button:active{transform:scale(.96)}
::view-transition-group(*){animation-duration:300ms;animation-timing-function:cubic-bezier(.22,1,.36,1)}
::view-transition-old(article-cover),::view-transition-new(article-cover){height:100%;object-fit:cover;border-radius:20px}
::view-transition-new(root){animation:art-appear 240ms ease both}
.heart-confirmed{color:var(--danger)!important}.heart-confirmed svg{animation:feedback-pop 300ms var(--ease)}.copy-confirmed svg{animation:feedback-pop 240ms var(--ease)}
