.series-part{position:relative}.series-part .part-number{position:relative;z-index:1;transition:color 180ms,background-color 180ms,box-shadow 200ms,transform 200ms}.series-part:not(:last-child):after{content:'';position:absolute;left:23px;top:60%;bottom:-45%;width:2px;background:var(--border);pointer-events:none}.series-part:is(:hover,:focus-visible) .part-number{background:var(--primary);color:var(--on-action);box-shadow:0 0 0 6px var(--subtle);transform:scale(1.06)}.series-part:is(:hover,:focus-visible):after{background:var(--primary)}.series-part>svg{transition:transform 200ms}.series-part:is(:hover,:focus-visible)>svg{transform:translateX(4px)}
