:root[data-motion=reduced] :is(a,button,section):hover,:root[data-motion=reduced] :is(a,button,section):hover :is(img,svg,.part-number){transform:none!important}

:root{transition:background-color 300ms ease,color 300ms ease}
@media(prefers-reduced-motion:reduce){:root{transition:none!important}}
:root[data-motion=reduced]{transition:none!important}

